/**
 * Emits app/assets/theme.css from app/lib/theme/signal.json.
 *
 * The generated file paints the first frame before any JavaScript runs. The
 * theme store then overrides individual properties on :root at runtime, so a
 * customised theme never needs a stylesheet rebuild.
 *
 * Run: node scripts/gen-theme-css.mjs  (wired into `npm run build`)
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const theme = JSON.parse(readFileSync(resolve(root, 'app/lib/theme/signal.json'), 'utf8'))

const SHADOW_LAYERS = {
  '2xs': [{ y: null, blur: null, mul: 0.5, spread: 0 }],
  xs: [{ y: null, blur: null, mul: 0.5, spread: 0 }],
  sm: [
    { y: null, blur: null, mul: 1, spread: 0 },
    { y: 1, blur: 2, mul: 1, spread: -1 },
  ],
  DEFAULT: [
    { y: null, blur: null, mul: 1, spread: 0 },
    { y: 1, blur: 2, mul: 1, spread: -1 },
  ],
  md: [
    { y: null, blur: null, mul: 1, spread: 0 },
    { y: 2, blur: 4, mul: 1, spread: -1 },
  ],
  lg: [
    { y: null, blur: null, mul: 1, spread: 0 },
    { y: 4, blur: 6, mul: 1, spread: -1 },
  ],
  xl: [
    { y: null, blur: null, mul: 1, spread: 0 },
    { y: 8, blur: 10, mul: 1, spread: -1 },
  ],
  '2xl': [{ y: null, blur: null, mul: 2.5, spread: 0 }],
}

const RADIUS_STEPS = [
  ['xs', 0.6],
  ['sm', 0.8],
  ['md', 1],
  ['lg', 1.4],
  ['xl', 1.8],
  ['2xl', 2.2],
  ['3xl', 2.6],
]

const TRACKING_STEPS = [
  ['tighter', -0.05],
  ['tight', -0.025],
  ['normal', 0],
  ['wide', 0.025],
  ['wider', 0.05],
  ['widest', 0.1],
]

const num = (v, fallback) => {
  const n = Number.parseFloat(v)
  return Number.isFinite(n) ? n : fallback
}

function shadows(values) {
  // `||` rather than `??`, matching deriveShadows in app/lib/theme/tokens.ts:
  // an emptied colour is a missing colour, not a shadow with no colour.
  const color = values['shadow-color'] || 'oklch(0 0 0)'
  const opacity = num(values['shadow-opacity'], 0.1)
  const blur = num(values['shadow-blur'], 3)
  const spread = num(values['shadow-spread'], 0)
  const x = num(values['shadow-offset-x'], 0)
  const y = num(values['shadow-offset-y'], 1)
  const out = {}
  for (const [name, layers] of Object.entries(SHADOW_LAYERS)) {
    out[name] = layers
      .map((l) => {
        const alpha = Math.min(1, Math.max(0, opacity * l.mul))
        const oy = l.y === null ? y : l.y
        const ob = l.blur === null ? blur : l.blur
        const os = spread + l.spread
        return `${x}px ${oy}px ${ob}px ${os}px color-mix(in oklab, ${color} ${(alpha * 100).toFixed(1)}%, transparent)`
      })
      .join(', ')
  }
  return out
}

function declarations(values, indent = '  ') {
  const lines = []
  for (const [key, value] of Object.entries(values)) {
    lines.push(`${indent}--${key}: ${value};`)
  }
  const base = num(values.radius, 0.625)
  const unit = /rem\s*$/.test(values.radius ?? '') ? 'rem' : 'px'
  for (const [name, mult] of RADIUS_STEPS) {
    lines.push(`${indent}--radius-${name}: ${Number((base * mult).toFixed(4))}${unit};`)
  }
  const tracking = num(values['letter-spacing'], 0)
  for (const [name, offset] of TRACKING_STEPS) {
    lines.push(`${indent}--tracking-${name}: ${Number((tracking + offset).toFixed(4))}em;`)
  }
  for (const [name, value] of Object.entries(shadows(values))) {
    lines.push(`${indent}--shadow${name === 'DEFAULT' ? '' : `-${name}`}: ${value};`)
  }
  return lines.join('\n')
}

const css = `/* Generated by scripts/gen-theme-css.mjs — do not edit by hand.
   Source of truth: app/lib/theme/signal.json
   Regenerate with: node scripts/gen-theme-css.mjs */

:root {
${declarations(theme.light)}
}

.dark {
${declarations(theme.dark)}
}
`

writeFileSync(resolve(root, 'app/assets/theme.css'), css)
console.log(`wrote app/assets/theme.css (${css.split('\n').length} lines)`)
